INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chess-for-idiots', 275246, '2024-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7bnm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4sjr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chess for Idiots', 'Chess for idiots - a discipline of intellectual sport, invented and initiated by Ozjasz Goldberg. Seemingly chess for idiots resembles regular chess. The game is played on the same board using the same pieces. However, this is where the similarities end, because everything that would discriminate intellectually against players was eliminated from the rules. Therefore, there are practically no rules, and players can make any move with any pieces and capture any number of opponent''s pieces. The victory is determined by the IQ (the lower, the greater the chances of winning) and the decision of Ozjasz Goldberg.' FROM games WHERE igdb_id = 275246 ON CONFLICT (game_id, language_code) DO NOTHING;
