INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('highway-drifter-hajwala-simulator', 284927, '2024-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob6x2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2q62.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Highway Drifter: Hajwala Simulator', 'Hajwala isn’t typical drifting, it’s a vibe straight from the Gulf streets. Drift the Arab way, go into high speed and lose control on the highway. It’s all about sliding sideways with style on highways and open roads, showing oﬀ your skills while staying in full control. It’s loud, wild, and a lot of fun. In Highway Drifter: Hajwala Simulator you get to feel all that energy. Whether you’re cruising the desert or speeding through mountain roads, Customize everything during gameplay, your car is all about your style. Pick your favorite shade of color and choose your tint level, switch up the rims, and mix and match front and back bumpers to match your style. You can even customize your license plate to make it totally yours.' FROM games WHERE igdb_id = 284927 ON CONFLICT (game_id, language_code) DO NOTHING;
