INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Death in Hyperspace', 'When your captain dies suspiciously halfway through a hyperspace transit, you know you’re in trouble. Not because you need a captain — as an embodied AI spaceship, you can pilot yourself just fine — but because, as an aficionado of mysteries and detective stories, you know there’s only one explanation: murder most foul.' FROM games WHERE igdb_id = 335836 ON CONFLICT (game_id, language_code) DO NOTHING;
