INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Area', 'Blue Area is an engaging RPG set in a city that has endured an apocalypse, governed by an AI known as Tai Yi. Players assume the role of a procurator tasked with unraveling the mystery behind Tai Yi''s betrayal of humanity. The game features a fully voice-acted narrative, enhanced by professional artists and a compelling script that immerses players in a story of rebellion against a self-created deity.' FROM games WHERE igdb_id = 350344 ON CONFLICT (game_id, language_code) DO NOTHING;
