INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Dragon: Virtual Pet Game', 'Meet your new virtual friend that looks and behaves like a real dragon. Just look at those majestic eyes and listen to its joyful roar. It will fill your heart with warmth and brighten your day. Play with your dragon, feed it yummy treats, take it on adventures, and enjoy endless fun. Show your dragon love, and it will return it tenfold. Take your dragon wherever you go; it''s always by your side.' FROM games WHERE igdb_id = 331361 ON CONFLICT (game_id, language_code) DO NOTHING;
