INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mayhem Mail', 'The mail has been scattered! Take on the mail route from hell, recover and deliver the mail to its rightful place! Mayhem Mail is a classic single screen arcade platformer in the vein of Donkey Kong, Bubble Bobble and Mario Bros. with some added puzzle elements.' FROM games WHERE igdb_id = 272746 ON CONFLICT (game_id, language_code) DO NOTHING;
