INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anomaly Patroller', 'Story: You are being hired to become an anomaly patroller. Your job is to investigate the area that is being haunted by anomalous activity through the special protocol. If there''s an anomaly, press the button then proceed. If there''s no anomaly, proceed without pressing the button. You must make it to area 20 to finish the protocol. Good luck.' FROM games WHERE igdb_id = 325240 ON CONFLICT (game_id, language_code) DO NOTHING;
