INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Funko Fusion', 'Funko Fusion is a third-person action game that’s all about celebrating fandom. Play with some of your favorite characters from across TV, movies, games, and comics, and explore handcrafted worlds inspired by Jurassic World, Back to the Future, JAWS, The Thing, Chucky, Battlestar Galactica, Hot Fuzz, The Umbrella Academy, Five Nights at Freddy’s, Masters of the Universe, Invincible, and many more!' FROM games WHERE igdb_id = 247567 ON CONFLICT (game_id, language_code) DO NOTHING;
