INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Submerged Mystery: Takodachi', 'Submerged Mystery: Takodachi is a top-down dungeon-crawling RPG featuring the Takodachis by Ninomae Ina''nis from hololive English. Players explore a sprawling labyrinth filled with puzzles, powerful enemies, and secrets tied to the enigmatic Ancient Ones. As you delve deeper, you unlock new abilities and summon skills from past Takodachis to aid in your journey. Elemental Affinities play a crucial role in combat, allowing players to strategize against the unique challenges posed by the Takodachis guarding the labyrinth.' FROM games WHERE igdb_id = 327399 ON CONFLICT (game_id, language_code) DO NOTHING;
