INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coreupt', 'An updated take on the classic 1v1 fighting game model, Coreupt enhances fighting mechanics by adding over-the-top special attacks. Take combat mastery to the next level by chaining normal, special, and cinematic attacks together with each character’s Coreupted mode to pull off a heavy-hitting combo. Follow the story of an unlikely party in their mission to stop an insatiable warlord in his pursuit of tyranny over the galaxies.' FROM games WHERE igdb_id = 130328 ON CONFLICT (game_id, language_code) DO NOTHING;
