INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '420Blaze It 2: Game of the Year', 'The long awaited sequel to the FPS hit is coming! You will no scope. You will blaze it. You will hallucinate some weird af s*** as you fight and xD inside your mind in 999fps to destroy the Illuminati and rescue the memes. Are you ready for 420BLAZEIT 2????!!1' FROM games WHERE igdb_id = 298607 ON CONFLICT (game_id, language_code) DO NOTHING;
