INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BT Biplanes Online', 'Challenge friends and players from all over the world in exciting one-on-one online battles. Pilot your biplane with precision and skill, maneuvering through intense dogfights and performing daring acrobatic maneuvers. Improve your biplane''s performance with powerful upgrades, fine-tuning its speed, maneuverability and firepower to suit your playstyle. Personalize your aircraft with unique camouflages to stand out on the battlefield. Master the art of air warfare, outwit your opponents and become the ultimate biplane ace.' FROM games WHERE igdb_id = 367187 ON CONFLICT (game_id, language_code) DO NOTHING;
