INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sainte-Vibrisse', 'A father and daughter set out for a peaceful camping holiday in the deep woods of rural Quebec. But when their car dies on a deserted road, their dream trip turns into a nightmare! No cell signal. No sign of life. Just an empty village, overrun with cats, strange happenings, and a supermarket that somehow… remains open despite no one inside. Are they truly alone? Or have they wandered into the heart of a dark and twisted cult? Sainte-Vibrisse awaits you… if you dare!' FROM games WHERE igdb_id = 322191 ON CONFLICT (game_id, language_code) DO NOTHING;
