INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ColorBlend FX: Desaturation', 'Descend into Splatland - the world of ColorBlend FX: Desaturation — a captivating mythical puzzle-platformer metroidvania that weaves a tale of glow, courage, and creativity. Join the Splatians, as they unite to restore the stolen essence back to their world, challenging the nefarious schemes of the dark entity, Lord Ashen. Splat''n''stomp juicy enemies, swim in paint pools, solve physics and color puzzles, and of course survive the death while figuring out the evil plans of the Lord.' FROM games WHERE igdb_id = 95024 ON CONFLICT (game_id, language_code) DO NOTHING;
