INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Umbra Fields', 'A Black and White Choose Your Own Adventure game in the Open World of the Umbra Fields. Customize who you are between 13 distinct classes, choose what nation you wish to be in, and explore to your heart''s content. Do quests, explore dungeons, fight, and discover your fate, and the fate of the world.' FROM games WHERE igdb_id = 272571 ON CONFLICT (game_id, language_code) DO NOTHING;
