INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Presence Lookout', 'Presence Lookout is an Observation spot the difference Horror game where the player has to spot different "anomalies" through the map. Anomalies can be anything from an object that has been moved to another location, rotated or even an unknown entity that shouldn''t be. Report the Anomalies to win!' FROM games WHERE igdb_id = 271873 ON CONFLICT (game_id, language_code) DO NOTHING;
