INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tape Art', 'Tape Art is a Tap to play Game, inspired by the infamous Italian Banana art "Comedian". In Tape Art, you tap anywhere on the screen to tape the Banana! There are more artifacts to tape to the wall and create more art like taping the Banana. You get every 3 chances to tap and tape at the exact point of time to stick, you fail when the banana won''t get taped properly and you lose.' FROM games WHERE igdb_id = 384207 ON CONFLICT (game_id, language_code) DO NOTHING;
