INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Terrorformer TD', 'Terrorformer TD is a tower defense roguelite where the map erodes and grows as the game progresses -- but the player gets terraforming tools to shape it! Every round, fortify your defenses to survive against waves of enemies; then cash in for new towers, upgrades, and other rewards. Gain XP and level up to unlock new abilities and components after each run and try again to make it even further!' FROM games WHERE igdb_id = 288958 ON CONFLICT (game_id, language_code) DO NOTHING;
