INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Rust', 'Red Rust is retro-style side-scrolling game which uniquely combines fighting mechanics with shooting mechanics. The game is heavily inspired by 8bit and 16bit hits of the 90s, but developed with the modern player in mind. Tons of great animation, hand-drawn backgrounds, variety of in-game situations and powerful soundtrack! Red Rust is only several hours long, but it is packed with boss battles, huge mechanical beasts, crazy plot twists and lots of fighting.' FROM games WHERE igdb_id = 146965 ON CONFLICT (game_id, language_code) DO NOTHING;
