INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons of Hinterberg', 'From developer Microbird, Dungeons of Hinterberg takes place in the Austrian Alps, where the small town of Hinterberg has become a tourist destination due to its lush scenery and crisp mountain air. And also monsters. It''s a great place to holiday if you want to kill some monsters.' FROM games WHERE igdb_id = 146917 ON CONFLICT (game_id, language_code) DO NOTHING;
