INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiles of Hope: Matching Games', 'Welcome to the Tiles of Hope! Get ready for an adventure filled with puzzles and mindblowing stories, from broken hearts to collapsing houses. Can you help the tiles family and create their happily ever after in tiles matching games? Let’s rebuild the dream and bring back the love. Together, we''ll match tiles and save the day. Time to rock that match-3 games for adults.' FROM games WHERE igdb_id = 331373 ON CONFLICT (game_id, language_code) DO NOTHING;
