INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marble-mechanics', 302526, '2024-05-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co88wj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2yqa.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Mechanics', 'An immersive VR experience, invites you to construct a marble run and simulate the mechanics of marbles running on the track. The track consists of elements that are easily customizable by simply grabbing them. From funnels and loops to spirals, splitters, and both vertical and horizontal turns, these track elements can automatically align themselves for a smooth marble run, making construction fast and easy. Group track elements together so you can grab the entire group. You have the ability to duplicate and delete individual track elements or entire groups, and save favorite groups to the Track Box for reuse at any time. Infinite undo/redo functionality is always available, and you can save your favorite runs for sharing, restoring, and simulating later.' FROM games WHERE igdb_id = 302526 ON CONFLICT (game_id, language_code) DO NOTHING;
