INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cannoneer', 323302, '2024-12-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co975d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar38s0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cannoneer', 'Cannoneer is a 2-dimensional, top down shooter game. You bomb planes to earn treasure and get new high scores. You can use that treasure to purchase skins and use those in game. The main gimmick of your cannon is that you only have one bomb. Every time the bomb leaves the screen you get it back. The cannon is stationary, but you can rotate in place at a set speed. The game mechanics include 30-second waves of planes that change direction and location every wave, speed increases per each wave, an explosive grenade that spawns after you shoot 15 times, and intense situations coupled with high-speed gameplay. You can track your best scores with the scores tab in the menu, and compete with your friends to get the best score. Good luck!' FROM games WHERE igdb_id = 323302 ON CONFLICT (game_id, language_code) DO NOTHING;
