INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fruit Slice by Motion Capture', 'This is a very classic fruit cutting game, but it is not controlled by a mouse or touch. Instead, it uses a camera to capture the trajectory of your arm and control the knife light to cut through the fruit . So,You only need a regular camera to experience the joy of real-time motion capture games.' FROM games WHERE igdb_id = 289261 ON CONFLICT (game_id, language_code) DO NOTHING;
