INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labyrinth of Shadows', 'Labyrinth Of Shadows immerses you in the heart of a mysterious forest, where danger lies in every shadow. Kidnapped by hordes of ninjas, you wake up in a locked room with one goal: escape. Armed only with your instincts, you must stealthily evade the relentless ninjas patrolling the labyrinthine forest.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 343625 AND ge.slug = 'tactical' ON CONFLICT DO NOTHING;
