INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ramas'' Call: Twisted Timing', 'Point and Click adventure in a medieval fantasy ambience. Imagine you are a random tabletop geek looking for new adventures and your friend makes a tiiny mistake with his time machine... Now add an adventurer, a noble and a detective and mix them all together in yourself. Must be fun, right?' FROM games WHERE igdb_id = 261734 ON CONFLICT (game_id, language_code) DO NOTHING;
