INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rapid Eye Madness', 'Rapid Eye Madness is a short grim & cute collection of mini-games that are as cryptic as they are engaging. Venture into the eldritch nightmare, and stream for your life as you solve the challenges the screens throw at you. Will you survive this eerie gamescape, or become another one of its victims?' FROM games WHERE igdb_id = 377631 ON CONFLICT (game_id, language_code) DO NOTHING;
