INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moai Alley', 'MoaiAlley is a mobile-friendly puzzle game that takes you to the Easter Island, where you help the Rapa Nui carve and transport the iconic Moai statues. You need to carve rocks, build roads, cut trees, and properly envision a way for the statues to be walked to their pedestals with the least moves possible.' FROM games WHERE igdb_id = 332802 ON CONFLICT (game_id, language_code) DO NOTHING;
