INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Rumble', 'Rocket Rumble is the racing party game! Combining the best parts of combat racing and fast-paced action fighting games, Rocket Rumble is a 1-4 player party game where a charming cast of animals in rocket suits smash and bash their way across the finish line. Rocket Rumble features single-screen, online multiplayer, and action-packed combat across 9 different obstacle courses.' FROM games WHERE igdb_id = 144974 ON CONFLICT (game_id, language_code) DO NOTHING;
