INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tower Hover', 'Tower Hover is an endless building game where players stack sections of a skyscraper to create the tallest structure possible. The goal is to align each new section perfectly on top of the previous one. If the placement isn''t accurate, the misaligned part gets cut off, making subsequent placements more challenging. The game ends when a section completely misses the tower. How high can you build before it all comes crashing down?' FROM games WHERE igdb_id = 314684 ON CONFLICT (game_id, language_code) DO NOTHING;
