INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eighth Era', 'The first game of its kind, rewarding competitive players with real-life collectibles. Embark on an epic journey 10,000 years in the future in Eighth Era! Join The Collector’s Society, battle digital monsters, and uncover powerful relics as you restore life to a world on the brink of collapse. With collectible coins and thrilling challenges, every victory brings you closer to a real-world reward. Dive into the adventure and experience a turn-based RPG like no other—where your virtual journey has real-world consequences!' FROM games WHERE igdb_id = 329967 ON CONFLICT (game_id, language_code) DO NOTHING;
