INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jett Rider', 'Jett Rider, the most unlikely hero stars in the biggest 2D adventure of the year. Save the planet Gravos, free its people, face the toughest bosses... And don''t forget to recycle! A collision in the orbit of the planet Gravos is the starting point of an unforgettable adventure with tons of fun and love for the classics. Jett, the space sweeper, was only supposed to pick up the wreckage of the AC-137 cargo ship, but he soon discovered that something messy was brewing on the surface of Gravos.' FROM games WHERE igdb_id = 260657 ON CONFLICT (game_id, language_code) DO NOTHING;
