INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow Bros. Wonderland', 'Boasting gorgeous 3D isometric graphics, Snow Bros. Wonderland has the brothers defending Snow Land from The Great King of Evil! Armed with an endless supply of ice pellets, gamers can turn monsters into snowballs which can be kicked to destroy a whole horde of enemies! Chain your attacks to defeat several bad guys at once and use your snowball skills to take down massive bosses.' FROM games WHERE igdb_id = 309256 ON CONFLICT (game_id, language_code) DO NOTHING;
