INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wastelander', 'Wastelander is a minimalist turn-based colony building game with roguelike and deckbuilding elements, where you start from nothing as a castaway on an alien world, build your colony, collect resources and protect yourself from mysterious and destructive atmospheric storms while using the secrets of the alien ruins to find a way to escape. As your colony expands you''ll find alien artifacts and buildings, perks, technology upgrades, and consumable items scattered across the map.' FROM games WHERE igdb_id = 178100 ON CONFLICT (game_id, language_code) DO NOTHING;
