INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bunny Haven', 'Welcome to Bunny Haven, where the enchantment of bunnies knows no bounds! Step into this irresistibly cute bunny game, where you take the reins of a bunny rescue sanctuary. Your mission: adopt and pamper adorable rescue bunnies, transform your garden into their loving haven, operate a cozy cafe, and play matchmaker for customers and their bunny buddies.' FROM games WHERE igdb_id = 383737 ON CONFLICT (game_id, language_code) DO NOTHING;
