INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GreenBulb', 'GreenBulb is a fun and colorful single-player jump-and-run game where you will be challenged in your skill and dexterity as you solve puzzles and tests of skill across 20 levels. GreenBulb has the ability to ‘convert’ a shape either by delivering a kick or by leaping onto it. Achieving multiple shape conversions without touching the ground will result in higher scores.' FROM games WHERE igdb_id = 340322 ON CONFLICT (game_id, language_code) DO NOTHING;
