INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spilled-mushrooms', 318152, '2024-09-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8vby.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3545.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spilled Mushrooms', 'Spilled Mushrooms is a card puzzle game with quick and charming puzzles. Using a small deck of critter cards, you need to strategically collect every mushroom from each region within a short number of turns. Each card has its own unique behaviors that can combo with - and against - other cards, leading to a complex system of synergies and sticky situations. Puzzles are procedurally generated, meaning every delivery is a completely one-of-a-kind challenge with at least one solution. While most of your deliveries can be completed with ease, some of them may leave you scrambling to collect that last mushroom!' FROM games WHERE igdb_id = 318152 ON CONFLICT (game_id, language_code) DO NOTHING;
