INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lisa: The Undone', 'Based on the setting and stories established in Lisa: The Painful and Lisa: The Joyful by Dingaling, LISA: The UNDONE reimagines the storyline of Lisa: The Joyful into a longer, unique experience all its own, with countless rewrites, resprites, and alterations to the setting, story and gameplay that make it a very different experience with its own messages and story to tell. Follow a... different Buddy Armstrong and Rando as they seek to understand themselves and explore the eccentric world they inhabit.' FROM games WHERE igdb_id = 297621 ON CONFLICT (game_id, language_code) DO NOTHING;
