INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zenless Zone Zero', 'Zenless Zone Zero is an all-new 3D action game from HoYoverse, here to provide a thrilling combat experience. Build a squad of up to three and begin your assault with Basic and Special Attacks. Dodge and Parry to neutralize your opponents'' counterattacks, and when they''re Stunned, unleash a powerful combo of Chain Attacks to finish them off! Remember, different opponents have different traits, and it would be prudent to use their weaknesses to your advantage.' FROM games WHERE igdb_id = 200551 ON CONFLICT (game_id, language_code) DO NOTHING;
