INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drone Attack: Pig Irruption', 'Drone Attack: Pig Irruption is a fast-paced, action-packed mobile game where players control drones to fend off a mischievous invasion of pigs. Utilize a variety of drones, including the powerful new Combat Mosquito, to strategically destroy waves of pigs. With exciting new features like soul absorption mechanics, quick bomb access, and a revamped interface, this game offers intense fun for those who enjoy tactical challenges and destruction. Join the battle, crush the pig invasion, and watch sunflowers grow where enemies fall!' FROM games WHERE igdb_id = 318901 ON CONFLICT (game_id, language_code) DO NOTHING;
